import argparse

class RomanConverter:
    ROMAN_NUMERAL_MAP = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    @classmethod
    def int_to_roman(cls, num):
        if not (0 < num < 4000):
            raise ValueError("Argument must be between 1 and 3999")
        result = []
        for (arabic, roman) in cls.ROMAN_NUMERAL_MAP:
            while num >= arabic:
                result.append(roman)
                num -= arabic
        return ''.join(result)

    @classmethod
    def roman_to_int(cls, s):
        s = s.upper()
        i = 0
        result = 0
        for arabic, roman in cls.ROMAN_NUMERAL_MAP:
            while s[i:i+len(roman)] == roman:
                result += arabic
                i += len(roman)
                if i >= len(s):
                    break
        # Validate result by converting back
        if cls.int_to_roman(result) == s:
            return result
        else:
            raise ValueError(f"Invalid Roman numeral: {s}")


def main():
    parser = argparse.ArgumentParser(description='Convert integers to Roman numerals and vice versa.')
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument('--to-roman', type=int, help='Convert integer to Roman numeral')
    group.add_argument('--to-int', type=str, help='Convert Roman numeral to integer')

    args = parser.parse_args()

    try:
        if args.to_roman is not None:
            print(RomanConverter.int_to_roman(args.to_roman))
        elif args.to_int is not None:
            print(RomanConverter.roman_to_int(args.to_int))
    except ValueError as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    main()
